17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Objects;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Guards owner creation against exact household duplicates. A household is keyed on last name and
26	 * postcode, but sharing a household is not by itself a duplicate: distinct people in the same
27	 * household are told apart by their telephone. Only a candidate that matches an existing household
28	 * member on telephone as well is a true re-registration and is rejected; a household member with a
29	 * different telephone is a legitimate new member, left to {@link PossibleDuplicateDetector} to flag
30	 * softly. Setting {@code sharesHousehold} declares the owner an intentional household member and
31	 * bypasses the block.
32	 */
33	@Component
34	public class HouseholdDuplicateValidator {
35	
36	    private final Households households;
37	
38	    public HouseholdDuplicateValidator(Households households) {
39	        this.households = households;
40	    }
41	
42	    /**
43	     * Reject {@code candidate} when an existing member of its household already carries the same
44	     * telephone (a true re-registration), unless it declares itself a shared-household member.
45	     * Household members with a different telephone are legitimate new members and are not rejected.
46	     *
47	     * @param candidate       the owner about to be created, with its {@code householdId} and
48	     *                        normalized telephone already set
49	     * @param sharesHousehold whether the owner opted into a shared household, bypassing the block
50	     * @throws HouseholdDuplicateException if a household member shares the candidate's telephone and
51	     * {@code sharesHousehold} is {@code false}
52	     */
53	    public void validate(Owner candidate, boolean sharesHousehold) {
54	        if (sharesHousehold) {
55	            return;
56	        }
57	        boolean exactDuplicate = households.findMembers(candidate).stream()
58	            .anyMatch(member -> Objects.equals(member.getTelephone(), candidate.getTelephone()));
59	        if (exactDuplicate) {
60	            throw new HouseholdDuplicateException(candidate.getHouseholdId());
61	        }
62	    }
63	}
