39	    @Mapping(target = "identityKey", expression = "java(owner == null ? null : ownerIdentity.key(owner))")
40	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
41	    @Mapping(target = "salutation", expression = "java(org.springframework.samples.petclinic.model.Salutation.forOwner(owner))")
42	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
43	    @Mapping(target = "telephoneDisplay", expression = "java(owner == null ? null : telephoneFormatter.format(owner.getTelephone()))")
44	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
45	    @Mapping(target = "membershipNumber", expression = "java(org.springframework.samples.petclinic.model.MembershipNumber.forOwner(owner))")
46	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.model.CheckDigit.forOwner(owner))")
47	    @Mapping(target = "membershipPoints", expression = "java(membershipLevelEvaluator.pointsFor(owner))")
48	    @Mapping(target = "membershipLevel", expression = "java(membershipLevelEvaluator.levelFor(owner))")
49	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
50	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
51	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarningEvaluator.isWarranted(owner))")
52	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.model.ContactPreference.forOwner(owner))")
53	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.model.AgeBand.forOwner(owner))")
54	    public abstract OwnerDto toOwnerDto(Owner owner);
55	
56	    /**
57	     * Builds an owner's canonical API path, {@code "/api/owners/<id>"}. Returns
58	     * {@code null} for a {@code null} owner or one that has not been assigned an id yet.
59	     */
60	    protected String formatSelfLink(Owner owner) {
61	        if (owner == null || owner.getId() == null) {
62	            return null;
63	        }
64	        return "/api/owners/" + owner.getId();
65	    }
66	
67	    /**
68	     * Derives an owner's fiscal year (starting 1 July) from its business-day-adjusted
69	     * registration date, formatted {@code "FY<YY>"}. Returns {@code null} for a {@code null}
70	     * owner or one whose registration date has not been assigned yet.
71	     */
72	    protected String formatFiscalYear(Owner owner) {
73	        if (owner == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        return org.springframework.samples.petclinic.model.FiscalYear
77	            .containing(owner.getRegistrationDate()).label();
78	    }
79	
80	    /**
81	     * Derives an owner's locality from its region-and-hash identity: the {@code <REGION>}
82	     * segment of the assigned {@code customerCode}. Owners without a code yet fall back to
83	     * deriving the region straight from their own fields.
84	     */
85	    protected String formatLocality(Owner owner) {
86	        if (owner == null) {
87	            return null;
88	        }
89	        if (owner.getCustomerCode() != null) {
90	            return org.springframework.samples.petclinic.model.Locality.fromCustomerCode(owner.getCustomerCode());
91	        }
92	        return org.springframework.samples.petclinic.model.Locality.forOwner(owner);
93	    }
94	
95	    /**
96	     * Derives an owner's IANA timezone from its locality region using the fixed
97	     * region-to-timezone table. Returns {@code null} for a {@code null} owner or when
98	     * the region has no known timezone.
99	     */
100	    protected String formatTimezone(Owner owner) {
101	        if (owner == null) {
102	            return null;
103	        }
104	        return org.springframework.samples.petclinic.model.RegionTimezone.forRegion(formatLocality(owner));
105	    }
106	
107	    /**
108	     * Formats an owner's stored names as {@code "LastName, FirstName"} for display.
109	     */
110	    protected String formatDisplayName(Owner owner) {
111	        if (owner == null) {
112	            return null;
113	        }
114	        return owner.getLastName() + ", " + owner.getFirstName();
115	    }
116	
117	    /**
118	     * Builds an owner's initials as the upper-cased first letters of the first and last
119	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
120	     */
121	    protected String formatInitials(Owner owner) {
122	        if (owner == null) {
123	            return null;
124	        }
125	        return initial(owner.getFirstName()) + initial(owner.getLastName());
126	    }
127	
128	    private String initial(String name) {
129	        return Character.toUpperCase(name.charAt(0)) + ".";
130	    }
131	
132	    public abstract Owner toOwner(OwnerDto ownerDto);
133	
134	    @Mapping(target = "id", ignore = true)
135	    @Mapping(target = "pets", ignore = true)
136	    @Mapping(target = "customerCode", ignore = true)
137	    @Mapping(target = "householdId", ignore = true)
138	    @Mapping(target = "namesakeCount", ignore = true)
139	    @Mapping(target = "possibleDuplicate", ignore = true)
140	    @Mapping(target = "possibleDuplicateOf", ignore = true)
141	    @Mapping(target = "deleted", ignore = true)
142	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
143	
144	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
145	
146	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
147	
148	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
149	        OwnerPageDto ownerPageDto = new OwnerPageDto();
150	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
151	        ownerPageDto.setPage(ownerPage.getNumber());
152	        ownerPageDto.setSize(ownerPage.getSize());
153	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
154	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
155	        return ownerPageDto;
156	    }
157	}
