    owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
    owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
    owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
    dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
    cityCapacityValidator.validate(owner);
    owner.setHouseholdId(households.householdId(owner));
    boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
    householdDuplicateValidator.validate(owner, sharesHousehold);
    if (sharesHousehold) {
        // A declared household member is not a suspected duplicate.
        owner.setPossibleDuplicate(false);
    } else {
        possibleDuplicateDetector.detect(owner);
    }
    this.clinicService.saveOwner(owner);
    ownerAuditLogger.logCreated(owner);
    ownerIdempotencyStore.record(idempotencyKey, owner.getId());
    OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
    headers.setLocation(UriComponentsBuilder.newInstance()
        .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
    return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
}

/**
 * If {@code idempotencyKey} has already been used to create an owner that still exists, returns
 * that originally created owner with 200 so the repeated create is a no-op; otherwise returns
 * {@code null} to let the create proceed normally.
 */
private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
    return ownerIdempotencyStore.find(idempotencyKey)
        .map(this.clinicService::findOwnerById)
        .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
        .orElse(null);
}

@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
@Override
public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
    Owner currentOwner = this.clinicService.findOwnerById(ownerId);
    if (currentOwner == null) {
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }
    currentOwner.setAddress(ownerFieldsDto.getAddress());
    currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
    currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
    addressResolver.resolve(currentOwner);
    currentOwner.setCity(ownerFieldsDto.getCity());
    currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
    currentOwner.setFirstName(ownerFieldsDto.getFirstName());
    currentOwner.setLastName(ownerFieldsDto.getLastName());
    currentOwner.setTelephone(ownerFieldsDto.getTelephone());
    currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
    this.clinicService.saveOwner(currentOwner);
    return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
}

@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
@Transactional
@Override
public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
    Owner owner = this.clinicService.findOwnerById(ownerId);
    if (owner == null) {
