        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.ownerFieldsValidator = ownerFieldsValidator;
        this.postcodeValidator = postcodeValidator;
        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
        this.telephoneNormalizer = telephoneNormalizer;
        this.emailNormalizer = emailNormalizer;
        this.addressResolver = addressResolver;
        this.households = households;
        this.householdDuplicateValidator = householdDuplicateValidator;
        this.possibleDuplicateDetector = possibleDuplicateDetector;
        this.cityCapacityValidator = cityCapacityValidator;
        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
        this.businessDayAdjuster = businessDayAdjuster;
        this.registrationDateValidator = registrationDateValidator;
        this.ownerAuditLogger = ownerAuditLogger;
        this.ownerIdempotencyStore = ownerIdempotencyStore;
    }

    /**
     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
     */
    @InitBinder("ownerFieldsDto")
    void initOwnerFieldsBinder(WebDataBinder binder) {
        binder.addValidators(ownerFieldsValidator, postcodeValidator, disposableEmailDomainValidator);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
        if (replay != null) {
            return replay;
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        addressResolver.resolve(owner);
        registrationDateValidator.validate(owner.getRegistrationDate());
        LocalDate registrationDate = owner.getRegistrationDate() != null
            ? owner.getRegistrationDate() : LocalDate.now();
        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
        cityCapacityValidator.validate(owner);
        owner.setHouseholdId(households.householdId(owner));
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        householdDuplicateValidator.validate(owner, sharesHousehold);
        if (sharesHousehold) {
            // A declared household member is not a suspected duplicate.
            owner.setPossibleDuplicate(false);
        } else {
            possibleDuplicateDetector.detect(owner);
        }
        this.clinicService.saveOwner(owner);
        ownerAuditLogger.logCreated(owner);
        ownerIdempotencyStore.record(idempotencyKey, owner.getId());
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * If {@code idempotencyKey} has already been used to create an owner that still exists, returns
     * that originally created owner with 200 so the repeated create is a no-op; otherwise returns
     * {@code null} to let the create proceed normally.
     */
    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
        return ownerIdempotencyStore.find(idempotencyKey)
            .map(this.clinicService::findOwnerById)
            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
            .orElse(null);
    }

